<script setup lang="ts">
import {ref,watch} from 'vue';import {useMetrics} from '../composables/poll';import {time} from '../money';import MetricChart from '../components/MetricChart.vue';import DataState from '../components/DataState.vue';import StatusBadge from '../components/StatusBadge.vue';
import LatencyMetrics from '../components/LatencyMetrics.vue';
const state=useMetrics();const samples=ref<{at:string;rate:number|null;queue:number|null;replicas:number|null}[]>([]);watch(state.data,v=>{if(v){const rate=Number(v.requestRate?.[0]?.value[1]??NaN);samples.value=[...samples.value,{at:v.refreshedAt,rate:Number.isFinite(rate)?rate:null,queue:v.queue?.ready??null,replicas:v.cluster?.deployments?.find(d=>d.name==='loan-worker')?.status.readyReplicas??null}].slice(-100)}});
function safeLink(url:string|null|undefined){return url&&/^https?:\/\//.test(url)?url:undefined}
</script>
<template><div class="page-title"><div><p class="eyebrow">OBSERVED TELEMETRY</p><h1>Scaling & observability</h1><p class="muted">{{state.data.value?.capacityNote??'Docker Desktop pods share one computer’s resources.'}}</p></div><span class="badge warn">{{state.data.value?.runtimeMode??'Connecting'}}</span></div><DataState :loading="state.loading.value" :error="state.error.value" :updated-at="state.updatedAt.value"/><div class="stat-grid"><div class="stat-card"><span>Ready payment messages</span><strong>{{state.data.value?.queue?.ready??'Unavailable'}}</strong><small>RabbitMQ management API</small></div><div class="stat-card"><span>In-flight messages</span><strong>{{state.data.value?.queue?.unacknowledged??'Unavailable'}}</strong><small>Manual acknowledgements</small></div><div class="stat-card"><span>Connected consumers</span><strong>{{state.data.value?.queue?.consumers??'Unavailable'}}</strong><small>Consumers include failure recovery</small></div><div class="stat-card"><span>Queue delivery rate</span><strong>{{state.data.value?.queue?.deliveryRate?.toFixed(1)??'Unavailable'}}</strong><small>Observed messages per second</small></div><div class="stat-card"><span>Autoscaling</span><strong class="small-stat">{{state.data.value?.autoscaling??'Unavailable'}}</strong></div><div class="stat-card"><span>Oldest message age</span><strong class="small-stat">Unavailable</strong><small>Pending outbox age is shown on Overview</small></div></div><LatencyMetrics :acceptance="state.data.value?.acceptanceLatency" :application="state.data.value?.applicationLatency"/><section class="panel"><div class="panel-heading"><div><h3>Receiver load, worker backlog & replicas</h3><p>Live samples share one timeline. Absent telemetry has no generated values.</p></div></div><MetricChart :samples="samples"/><p class="chart-note">Source: RabbitMQ management, Prometheus and read-only Kubernetes API. Refreshed {{time(state.data.value?.refreshedAt)}}.</p></section>
<section class="panel"><div class="panel-heading"><h3>Deployment replicas</h3></div><el-table v-if="state.data.value?.cluster" :data="state.data.value.cluster.deployments"><el-table-column prop="name" label="Deployment"/><el-table-column prop="replicas" label="Desired"/><el-table-column prop="status.replicas" label="Current"/><el-table-column prop="status.readyReplicas" label="Ready"/></el-table><el-empty v-else :description="state.data.value?.autoscaling??'Telemetry unavailable'"/><el-collapse v-if="state.data.value?.cluster"><el-collapse-item title="HPA metrics / targets"><pre>{{JSON.stringify(state.data.value.cluster.hpa,null,2)}}</pre></el-collapse-item><el-collapse-item title="KEDA trigger status"><p>Initial queue-length target: 100 messages per worker replica.</p><pre>{{JSON.stringify(state.data.value.cluster.keda,null,2)}}</pre></el-collapse-item><el-collapse-item title="Pod scheduling state"><el-table :data="state.data.value.cluster.pods"><el-table-column prop="name" label="Pod"/><el-table-column prop="status.phase" label="Phase"/></el-table></el-collapse-item></el-collapse></section><section class="panel"><div class="panel-heading"><h3>Dependencies & tools</h3></div><div v-for="(dep,name) in state.data.value?.dependencies" :key="name" class="dependency"><span>{{name}} · {{dep.source}}</span><StatusBadge :status="dep.status"/></div><div class="tool-links"><a v-if="safeLink(state.data.value?.grafanaUrl)" :href="safeLink(state.data.value?.grafanaUrl)" target="_blank" rel="noopener">Open Grafana ↗</a><a v-if="safeLink(state.data.value?.traceUrl)" :href="safeLink(state.data.value?.traceUrl)" target="_blank" rel="noopener">Open trace viewer ↗</a></div><p class="chart-note">Observability tools require the Compose observability profile or equivalent Kubernetes services.</p></section></template>

